mod audio;mod game;mod video;
use game::Game;
fn main(){let mut captures=Vec::new();for (source,handler,state,x,stage,page,boss_remaining) in [(5,0xb7d8,5,80u16,0,0,0),(5,0xb7d8,5,280,0,0,0),(5,0xb7d8,5,80,5,13,0),(7,0x8112,4,80,0,0,0),(7,0x8112,4,280,0,0,0),(18,0x957c,4,80,0,0,1),(18,0x957c,4,80,0,0,2),(33,0x8ee9,4,80,0,0,0)]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x720]=source;g.memory[0x520]=state;g.memory[0x500]=76;g.memory[0x540]=2;g.memory[0x6a]=64;g.memory[0x710]=x as u8;g.memory[0x6f0]=(x>>8)as u8;g.memory[0x560]=80;g.memory[0x30]=stage;g.memory[0x43]=page;g.memory[0x3b]=boss_remaining;g.memory[0x660]=7;let mut samples=Vec::new();for tick in 0..40{g.memory[0x1a]=tick;let sounds=g.death_call(handler).unwrap();samples.push(serde_json::json!({"tick":tick,"sprite":g.memory[0x500],"palette":g.memory[0x540],"flips":g.memory[0x6a],"alive":g.memory[0x720]!=0,"sounds":sounds}));if g.memory[0x720]==0{break;}}captures.push(serde_json::json!({"source":source,"x":x,"stage":stage,"page":page,"boss_remaining":boss_remaining,"samples":samples}));}println!("{}",serde_json::to_string_pretty(&captures).unwrap());}
